-- ===============================================================
-- universe65: 🏪 클로버 스파 (clover-spa) 메뉴 · 가격 다시 맞추기 (2026-11-28)
--  출처: 가게 공식 가격표 (베트남어판 cloverspa.vn/bang-gia-clover-spa.html 이미지 · 영어판 /en/price-list.html)
--       + 서비스 소개 페이지의 '소요 시간' (cloverspa.vn/kr/dich-vu/)
--  메뉴 34개 → 48개
--  · 가격 고침: 베트남 전통 마사지 60분 550,000 → 570,000 · 90분 780,000 → 800,000
--  · 가격표에 있는데 빠졌던 것: 핫스톤 90분 780,000 · 임산부 60분 550,000 · 타이 90분 800,000
--      핫스톤 + 허브 70분 670,000 · 90분 820,000 · 페이셜 4가지 (내추럴 60분 420,000 · 브라이트닝 60분 440,000 · 비타민C 70분 500,000 · 기본 45분 395,000)
--  · 소개 페이지엔 시간이 있는데 가격표엔 가격이 없는 것 → '가격 상담'으로 추가 (가게가 '가격은 핫라인 문의'라고 적어 둠)
--      키즈 120분 · 스웨디시 120분 · 타이 120분 · 클로버 시그니처(달팽이) 60분 · 120분
--  · 바꾸기 전 메뉴는 shop_sources.crawled.menu_before_u65 에 백업 (되돌리기 SQL 은 맨 아래 주석)
--  · 그사이 관리자 화면에서 클로버 메뉴를 고쳤으면(34개가 아니면) 덮어쓰지 않아요
-- Supabase → SQL Editor 에 붙여 넣고 Run (여러 번 실행해도 결과는 같아요)
-- ===============================================================

-- 1) 백업 (처음 한 번만)
insert into public.shop_sources (shop_id, crawled)
select 'clover-spa', '{}'::jsonb where not exists (select 1 from public.shop_sources where shop_id = 'clover-spa');
update public.shop_sources src
   set crawled = coalesce(src.crawled, '{}'::jsonb) || jsonb_build_object('menu_before_u65', s.data->'menu')
  from public.shops s
 where s.id = src.shop_id and s.id = 'clover-spa'
   and not (coalesce(src.crawled, '{}'::jsonb) ? 'menu_before_u65');

